const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  const question = (body.question || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  if (!question) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'question requerida' } }];
  if (question.length > 1000) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'question demasiado larga (max 1000 chars)' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    question,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Validate').first().json;
const rows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (rows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404 } }];
const project = rows[0];
const city = (project.location_city || '').trim();
if (!city) return [{ json: { _error: 'PROJECT_NO_CITY', _status: 400, _details: 'El proyecto no tiene location_city. No puedo consultar normativa municipal.' } }];
// Slug determinista JS (sin depender de unaccent extension en Postgres)
const slug = city.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60);
return [{ json: { ...sess, project_id: project.id, project_name: project.name, municipio_slug: slug, location_city: city, location_province: project.location_province } }];

const emb = $('Embed Question').first().json;
const sess = $('Resolve Project').first().json;
const vec = emb?.data?.[0]?.embedding;
if (!Array.isArray(vec)) return [{ json: { ...sess, _error: 'EMBED_FAILED', _status: 502, _details: 'OpenAI no devolvio embedding valido' } }];
// pgvector acepta el formato [0.1,0.2,...] como string castable a vector
return [{ json: { ...sess, embedding_str: '[' + vec.join(',') + ']' } }];

const sess = $('Resolve Project').first().json;
const rules = $input.all().map(i => i.json).filter(r => r && r.id);
return [{ json: { ...sess, rules, rules_count: rules.length } }];

