const llm = $('Synthesize Answer (gpt-4o)').first().json;
const agg = $('Aggregate Rules').first().json;
let parsed = { respuesta: '', citas: [], confianza: 'baja' };
try {
  const content = llm?.choices?.[0]?.message?.content;
  const j = typeof content === 'string' ? JSON.parse(content) : content;
  parsed = {
    respuesta: j.respuesta || 'No tengo informacion suficiente.',
    citas: Array.isArray(j.citas) ? j.citas.slice(0, 3) : [],
    confianza: ['alta','media','baja'].includes(j.confianza) ? j.confianza : 'baja',
  };
} catch (e) {
  parsed = { respuesta: 'Error al sintetizar respuesta. Revisa la pregunta o consulta la sede electronica del ayuntamiento.', citas: [], confianza: 'baja' };
}
return [{ json: {
  tenant_id: agg.tenant_id,
  project_id: agg.project_id,
  question: agg.question,
  rules_count: agg.rules_count,
  ...parsed,
  request_id: agg.request_id,
  location_city: agg.location_city
}}];
